static BindingFlags f=BindingFlags.Instance|BindingFlags.NonPublic;static object Get(object o,string n){return o.GetType().GetField(n,f).GetValue(o);}static void Set(object o,string n,object value){o.GetType().GetField(n,f).SetValue(o,value);}static void Call(object o,string n,params object[] args){o.GetType().GetMethod(n,f).Invoke(o,args);}static void Pump(int ms){var w=Stopwatch.StartNew();while(w.ElapsedMilliseconds<ms){Application.DoEvents();System.Threading.Thread.Sleep(2);}}
static void Wait(Func<bool> done,string reason,int timeout=14000){var w=Stopwatch.StartNew();while(!done()&&w.ElapsedMilliseconds<timeout)Pump(10);if(!done())throw new Exception("Timeout: "+reason);}
static double Position(Form p){return (double)Get(p,"position");}
static void Settled(Form p){Pump(80);Wait(()=>!(bool)Get(p,"navigating")&&Get(p,"pendingSeek")==null&&((System.Collections.ICollection)Get(p,"frames")).Count==0,"navigation completion");if(((Label)Get(p,"details")).Text.Contains("초과")||((Label)Get(p,"details")).Text.Contains("지연"))throw new Exception(((Label)Get(p,"details")).Text);}
static void Near(double a,double b,double tol,string name){Console.WriteLine(name+": "+a.ToString("0.000")+" expected "+b.ToString("0.000"));if(Math.Abs(a-b)>tol)throw new Exception(name);}
[System.Runtime.InteropServices.DllImport("user32.dll")]static extern bool SetCursorPos(int x,int y);
[System.Runtime.InteropServices.DllImport("user32.dll")]static extern void mouse_event(uint flags,uint x,uint y,uint data,UIntPtr extra);
static void Click(Point point){SetCursorPos(point.X,point.Y);Pump(100);mouse_event(2,0,0,0,UIntPtr.Zero);Pump(50);mouse_event(4,0,0,0,UIntPtr.Zero);Pump(150);}
