Pump(700);using(var image=new Bitmap(800,450)){using(var graphics=Graphics.FromImage(image))graphics.CopyFromScreen(((Control)Get(p,"host")).PointToScreen(new Point(180,180)),Point.Empty,image.Size);int colored=0;for(int y=0;y<image.Height;y+=10)for(int x=0;x<image.Width;x+=10){var c=image.GetPixel(x,y);if(Math.Max(c.R,Math.Max(c.G,c.B))-Math.Min(c.R,Math.Min(c.G,c.B))>60)colored++;}if(colored<100)throw new Exception("Video output is blank");Console.WriteLine("PASS rendered video pixels "+colored);}
